import dspy
from dspy.utils.dummies import DummyLM


dspy.configure(
    lm=DummyLM(
        {
            'q1': {'answer': 'alpha'},
            'q2': {'answer': 'wrong'},
        }
    )
)


devset = [
    dspy.Example(question='q1', answer='alpha').with_inputs('question'),
    dspy.Example(question='q2', answer='beta').with_inputs('question'),
]
program = dspy.Predict('question -> answer')


def metric(example, pred, trace=None):
    if pred.answer == example.answer:
        return dspy.Prediction(score=1.0, feedback='exact match')
    return dspy.Prediction(score=0.25, feedback=f'expected {example.answer}, got {pred.answer}')


result = dspy.Evaluate(devset=devset, metric=metric, num_threads=1, display_progress=False)(program)
score_objects = [score for _, _, score in result.results]

print('aggregate =', result.score)
print('score_objects =', score_objects)

assert result.score == 62.5
assert isinstance(score_objects[0], dspy.Prediction)
assert [score.score for score in score_objects] == [1.0, 0.25]
assert score_objects[0].feedback == 'exact match'
assert score_objects[1].feedback == 'expected beta, got wrong'
