import dspy


example = dspy.Example(question='Q', answer='A').with_inputs('question')


def only_inputs(question):
    return {'question': question}


def full_example(example):
    return {'question': example.question, 'has_answer': hasattr(example, 'answer')}


default_parallel = dspy.Parallel(num_threads=1, disable_progress_bar=True)
full_parallel = dspy.Parallel(num_threads=1, disable_progress_bar=True, access_examples=False)

default_result = default_parallel([(only_inputs, example)])[0]
full_result = full_parallel([(full_example, example)])[0]

print('default_result =', default_result)
print('full_result =', full_result)

assert default_result == {'question': 'Q'}
assert full_result == {'question': 'Q', 'has_answer': True}
